            "text": "{\"findings\":[{\"tipo\":\"GC\",\"causa_raiz\":\"Alocação excessiva de memória gerenciada dentro do método Update() em StressTestScene (mais de 5.4 MB alocados em um único frame), disparando coletas de lixo síncronas frequentes do Garbage Collector com pausas de até 25.84 ms, ultrapassando amplamente o orçamento de 16.7 ms por frame.\",\"codigo_refatorado\":\"using UnityEngine;\\\\nusing System.Collections.Generic;\\\\n\\\\nnamespace PerformanceAdvisor.StressTest\\\\n{\\\\n    public class StressTestScene : MonoBehaviour\\\\n    {\\\\n        [SerializeField] private int bufferCapacity = 1024;\\\\n        private List\u003cVector3\u003e cachedPositionBuffer;\\\\n        private byte[] reusableDataBuffer;\\\\n\\\\n        private void Awake()\\\\n        {\\\\n            cachedPositionBuffer = new List\u003cVector3\u003e(bufferCapacity);\\\\n            reusableDataBuffer = new byte[bufferCapacity];\\\\n        }\\\\n\\\\n        private void Update()\\\\n        {\\\\n            cachedPositionBuffer.Clear();\\\\n            ProcessDataNonAlloc(cachedPositionBuffer, reusableDataBuffer);\\\\n        }\\\\n\\\\n        private void ProcessDataNonAlloc(List\u003cVector3\u003e positions, byte[] buffer)\\\\n        {\\\\n            for (int i = 0; i \u003c positions.Capacity; i++)\\\\n            {\\\\n                positions.Add(transform.position);\\\\n                buffer[i] = (byte)(i % 256);\\\\n            }\\\\n        }\\\\n    }\\\\n}\",\"explicacao_didatica\":\"Toda vez que você cria listas, arrays ou novos objetos dentro do método Update(), o Unity aloca memória dinâmica temporária. Quando essa memória se acumula, o Garbage Collector (o coletor de lixo da memória) precisa pausar a execução do jogo para fazer a limpeza, gerando travamentos perceptíveis (stuttering). Para resolver isso, alocamos os buffers e listas uma única vez no Awake() ou Start() e apenas limpamos e reutilizamos esses mesmos recursos a cada frame usando métodos como List.Clear(), zerando a geração de lixo.\"}],\"dicas_level_design\":null}",
